class TestBuildModels(unittest.TestCase):
    def test_converts_ids_to_models_map(self):
        models = build_models([{"id": "model-1"}])
        self.assertEqual(models, {"model-1": {"name": "model 1"}})

    def test_uses_display_name_when_present(self):
        models = build_models([{"id": "model-1", "display_name": "Model One"}])
        self.assertEqual(models["model-1"]["name"], "Model One")

    def test_ignores_display_name_matching_id(self):
        models = build_models([{"id": "model-1", "display_name": "model-1"}])
        self.assertEqual(models["model-1"]["name"], "model 1")

    def test_drops_duplicate_and_unusable_entries(self):
        models = build_models([{"id": "model-1"}, {"id": "model-1"}, {"id": ""}, {}])
        self.assertEqual(list(models), ["model-1"])

    def test_preserves_existing_metadata(self):
        models = build_models(
            [{"id": "model-1"}],
            existing={"model-1": {"name": "old", "limit": {"context": 128000}}},
        )
        self.assertEqual(models["model-1"]["name"], "model 1")
        self.assertEqual(models["model-1"]["limit"], {"context": 128000})

    def test_drops_model_ids_the_provider_no_longer_returns(self):
        models = build_models([{"id": "model-2"}], existing={"model-1": {"name": "x"}})
        self.assertEqual(list(models), ["model-2"])

    def test_all_versions_keeps_every_version(self):
        models = build_models([{"id": "model-3"}, {"id": "model-4"}])
        self.assertEqual(list(models), ["model-3", "model-4"])

    def test_latest_only_collapses_one_family(self):
        models = build_models(
            [{"id": "gpt-4o"}, {"id": "gpt-4o-mini"}], latest_only=True
        )
        self.assertEqual(list(models), ["gpt-4o-mini"])

    def test_rejects_empty_model_list(self):
        with self.assertRaises(RefreshError):
            build_models([])


class TestConfigShapes(unittest.TestCase):
    def test_reads_v2_providers(self):
        config = {"providers": {"p": {"models": {"m": {"name": "M"}}}}}
        self.assertEqual(provider_entry(config, "p")["models"], {"m": {"name": "M"}})

    def test_reads_legacy_provider(self):
        config = {"provider": {"p": {"models": {"m": {"name": "M"}}}}}
        self.assertEqual(existing_models(config, "p"), {"m": {"name": "M"}})

    def test_missing_provider_is_empty(self):
        self.assertEqual(provider_entry({"providers": {}}, "p"), {})
        self.assertEqual(existing_models({}, "p"), {})

    def test_base_url_comes_from_provider_settings(self):
        config = {"providers": {"p": {"settings": {"baseURL": "https://p.example"}}}}
        self.assertEqual(provider_base_url(config, "p"), "https://p.example")

    def test_base_url_falls_back_to_options(self):
        config = {"providers": {"p": {"options": {"baseURL": "https://p.example"}}}}
        self.assertEqual(provider_base_url(config, "p"), "https://p.example")

    def test_base_url_absent(self):
        self.assertIsNone(provider_base_url({"providers": {"p": {}}}, "p"))

    def test_declared_env_names(self):
        config = {"providers": {"p": {"env": ["ENMAAS_KEY", 7]}}}
        self.assertEqual(provider_env_names(config, "p"), ["ENMAAS_KEY"])

    def test_fragment_wraps_models_under_the_requested_shape(self):
        models = {"m": {"name": "M"}}
        self.assertEqual(
            fragment("p", models, shape="providers"), {"providers": {"p": {"models": models}}}
        )
        self.assertEqual(
            fragment("p", models, shape="provider"), {"provider": {"p": {"models": models}}}
        )


class TestMain(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.tmp_path = Path(self._tmp.name)
        self.config = self.tmp_path / "opencode.json"
        self.output = self.tmp_path / "15-models.json"

    def _args(self, *extra):
        return [
            "--provider",
            "p",
            "--url",
            "https://provider.example",
            "--token",
            "secret",
            "--config",
            str(self.config),
            "--output",
            str(self.output),
            *extra,
        ]

    def _run(self, *extra, entries=None):
        with mock.patch(
            "scripts.refresh_models.fetch_models",
            return_value=entries if entries is not None else [{"id": "model-1"}],
        ):
            return main(self._args(*extra))

    def test_dry_run_prints_without_writing(self):
        import io
        from contextlib import redirect_stdout

        buffer = io.StringIO()
        with redirect_stdout(buffer):
            result = self._run("--dry-run")

        self.assertEqual(result, 0)
        self.assertEqual(
            json.loads(buffer.getvalue()),
            {"providers": {"p": {"models": {"model-1": {"name": "model 1"}}}}},
        )
        self.assertFalse(self.output.exists())

