    def test_updates_config_in_place(self):
        self.config.write_text(
            json.dumps(
                {
                    "model": "enmaas/model-1",
                    "providers": {
                        "p": {
                            "name": "P",
                            "env": ["P_KEY"],
                            "package": "@opencode/ai/providers/openai-compatible",
                            "settings": {"baseURL": "https://configured.example"},
                            "models": {
                                "retired-1": {"name": "Retired"},
                                "model-1": {"name": "old", "limit": {"context": 1000}},
                            },
                        }
                    },
                }
            )
        )
        with mock.patch(
            "scripts.refresh_models.fetch_models",
            return_value=[{"id": "model-1"}, {"id": "model-2"}],
        ):
            import io
            from contextlib import redirect_stdout

            with redirect_stdout(io.StringIO()):
                result = main(
                    [
                        "--provider",
                        "p",
                        "--token",
                        "secret",
                        "--config",
                        str(self.config),
                    ]
                )

        self.assertEqual(result, 0)
        document = json.loads(self.config.read_text())
        self.assertEqual(document["model"], "enmaas/model-1")
        entry = document["providers"]["p"]
        self.assertEqual(entry["package"], "@opencode/ai/providers/openai-compatible")
        self.assertEqual(entry["settings"], {"baseURL": "https://configured.example"})
        self.assertEqual(list(entry["models"]), ["model-1", "model-2"])
        self.assertEqual(entry["models"]["model-1"]["limit"], {"context": 1000})
        self.assertEqual(entry["models"]["model-2"], {"name": "model 2"})

